def _validate_key(key: str) -> None:
    if not key:
        raise ValueError("Key must not be empty")
    for ch in key:
        if not ch.isalpha() or not ch.isascii():
            raise ValueError("Key must contain only ASCII letters")


def vigenere_encrypt(text: str, key: str) -> str:
    _validate_key(key)
    key_lower = key.lower()
    key_len = len(key_lower)
    result = []
    key_idx = 0
    for ch in text:
        if ch.isalpha() and ch.isascii():
            shift = ord(key_lower[key_idx]) - ord('a')
            if ch.isupper():
                base = ord('A')
            else:
                base = ord('a')
            new_code = (ord(ch) - base + shift) % 26 + base
            result.append(chr(new_code))
            key_idx = (key_idx + 1) % key_len
        else:
            result.append(ch)
    return ''.join(result)


